    String extractResult(String regex,VulnApp.Reply reply){if(regex.isBlank()||reply==null)return "";var match=java.util.regex.Pattern.compile(regex).matcher(WorkbenchCore.raw(reply));return match.find()?match.group(match.groupCount()>0?1:0):"";}
    void generateNumbers(){JTextField from=new JTextField("1"),to=new JTextField("10"),step=new JTextField("1");if(JOptionPane.showConfirmDialog(app,new Object[]{"From",from,"To",to,"Step",step},"Numeric payloads",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{long a=Long.parseLong(from.getText()),b=Long.parseLong(to.getText()),d=Long.parseLong(step.getText());if(d<=0||b<a||b-a>1000000)throw new IllegalArgumentException("Use an ascending bounded range and positive step");StringBuilder out=new StringBuilder();int count=0;for(long n=a;n<=b;n+=d){if(++count>5000)throw new IllegalArgumentException("Maximum 5000 payloads");out.append(n).append("\n");if(n>Long.MAX_VALUE-d)break;}payloads.setText(out.toString());}catch(Exception ex){app.error(ex);}}
