    void startScan(){if(scanJob!=null&&!scanJob.isDone()){app.log("Scanner já está executando.");return;}URI uri;try{uri=VulnApp.Packet.checked(URI.create(scanUrl.getText()));}catch(Exception ex){app.error(ex);return;}int max=(int)pages.getValue(),delay=(int)scanDelay.getValue();boolean probe=active.isSelected();stopScan.set(false);scanJob=app.workers.submit(()->{try{if(app.workspace!=null&&app.workspace.dynamicCrawl.isSelected()){app.workspace.scanDynamic(uri,max,delay,stopScan);return;}WorkbenchCore.scan(uri,max,probe,delay,stopScan,this::finding,(packet,url,reply)->SwingUtilities.invokeLater(()->app.addExchange(packet,url,reply,0,"Scanner")));app.log(stopScan.get()?"Scanner interrompido.":"Scanner concluído — somente mesma origem; sem seguir redirects externos.");}catch(Exception ex){app.error(ex);}});}
    void inspect(VulnApp.Exchange exchange,VulnApp.Reply reply){if(loading||exchange.method().equals("CONNECT"))return;if(passive.isSelected())ScannerChecks.inspect(URI.create(exchange.url()),reply,app.workspace==null?List.of():app.workspace.compiledChecks).forEach(this::finding);if(!extensions.isEmpty())app.workers.submit(()->{for(var extension:extensions)try{List<ReaExtension.Issue> result=extension.plugin.inspect(exchange.method(),exchange.url(),exchange.request().clone(),exchange.response().clone());if(result!=null)for(var issue:result)finding(new WorkbenchCore.Finding(issue.severity(),issue.title(),exchange.url(),issue.evidence(),"Extension: "+extension.plugin.name()));}catch(Throwable ex){app.log("Extension failed: "+ex.getMessage());}});}
