    void report(){Path path=choose("rea-scan-report.html",true);if(path==null)return;StringBuilder b=new StringBuilder("<!doctype html><meta charset=utf-8><title>REA scan report</title><style>body{font:16px system-ui;max-width:1000px;margin:40px auto}article{padding:20px;border:1px solid #bbb;margin:12px 0}pre{white-space:pre-wrap}</style><h1>VULN scan report</h1><p>Catálogo limitado. Achados exigem avaliação no contexto do alvo. Reflexão não comprova XSS.</p>");for(var f:findings)b.append("<article><h2>").append(html(f.severity()+" · "+f.title())).append("</h2><p>").append(html(f.url())).append("</p><pre>").append(html(f.evidence())).append("</pre><p>").append(html(f.confidence())).append("</p></article>");try{Files.writeString(path,b.toString());app.log("Report saved: "+path);}catch(Exception ex){app.error(ex);}}
