    void collectTokens(){if(tokenJob!=null&&!tokenJob.isDone())return;String raw=app.repeaterRequest.getText(),url=app.repeaterUrl.getText(),regex=tokenRegex.getText();int count=(int)tokenSamples.getValue();java.util.regex.Pattern pattern;try{if(regex.length()>1000)throw new IllegalArgumentException("Regex excede 1000 caracteres");pattern=java.util.regex.Pattern.compile(regex);if(pattern.matcher("").groupCount()<1)throw new IllegalArgumentException("Regex deve ter grupo de captura");}catch(Exception ex){app.error(ex);return;}stopTokens.set(false);tokenJob=app.workers.submit(()->{try{var packet=VulnApp.parse(raw.getBytes(VulnApp.WIRE));URI uri=packet.uri(url);for(int i=0;i<count&&!stopTokens.get();i++){long start=System.nanoTime();var reply=VulnApp.perform(packet,uri);var match=pattern.matcher(WorkbenchCore.raw(reply));if(match.find()){String token=match.group(1);SwingUtilities.invokeLater(()->tokens.append(token+"\n"));}long ms=(System.nanoTime()-start)/1000000;SwingUtilities.invokeLater(()->app.addExchange(packet,uri,reply,ms,"Sequencer"));Thread.sleep(100);}SwingUtilities.invokeLater(this::analyzeTokens);}catch(Exception ex){app.error(ex);}});}
