    JPanel tls(){JPanel p=page();p.add(bar(button("Create local CA",this::createCA),button("Load CA keystore…",this::loadCA),button("Save CA keystore…",this::saveCA),button("Export CA certificate…",this::exportCA),tlsEnabled),BorderLayout.NORTH);tlsInfo.setLineWrap(true);tlsInfo.setWrapStyleWord(true);tlsInfo.setText("HTTPS MITM é opcional e começa desativado.\n\nCrie uma CA local ou carregue seu keystore PKCS#12. Exporte somente o certificado público e configure a confiança manualmente no cliente de teste. A aplicação nunca instala a CA no Windows ou navegador.\n\nA chave privada só é salva se você escolher Save CA keystore, com sua senha (mínimo 12 caracteres). A senha não é gravada pela aplicação.\n\nQuando ativado, CONNECT termina TLS localmente e encaminha HTTP/1.1 ao destino por HTTPS com validação padrão de certificado. Request e response passam pelo fluxo de interceptação/histórico. Sem CA confiada, o cliente rejeita o handshake.\n\nCertificados com pinning e clientes com autenticação TLS mútua não são suportados. HTTP/2 e HTTP/3 não são implementados. Desativar MITM restaura o túnel transparente para novas conexões.");p.add(titled("Certificate authority / trust",tlsInfo));tlsEnabled.addActionListener(e->{if(tlsEnabled.isSelected()&&authority==null){tlsEnabled.setSelected(false);app.log("Crie ou carregue uma CA primeiro.");return;}app.proxy.authority=authority;app.proxy.mitm=tlsEnabled.isSelected();app.log(app.proxy.mitm?"HTTPS MITM ativado para novas conexões.":"HTTPS MITM desativado.");});return p;}
